/// Perform a single‐step, root‐only peephole optimization.
pub fn optimize(e: Exp) -> Exp {
    match e {
        // Multiplication peepholes
        Exp::Mult(lhs, rhs) => {
            // Take ownership of the subexpressions
            let lhs = *lhs;
            let rhs = *rhs;
            match (lhs, rhs) {
                // Absorbing zero
                (Exp::Const(0), _) | (_, Exp::Const(0)) => Exp::Const(0),
                // Neutral one
                (Exp::Const(1), e2) => e2,
                (e1, Exp::Const(1)) => e1,
                // Constant folding
                (Exp::Const(a), Exp::Const(b)) => Exp::Const(a * b),
                // Otherwise no change
                (e1, e2) => Exp::Mult(Box::new(e1), Box::new(e2)),
            }
        }

        // Addition peepholes
        Exp::Plus(lhs, rhs) => {
            let lhs = *lhs;
            let rhs = *rhs;
            match (lhs, rhs) {
                // Neutral zero
                (Exp::Const(0), e2) => e2,
                (e1, Exp::Const(0)) => e1,
                // Constant folding
                (Exp::Const(a), Exp::Const(b)) => Exp::Const(a + b),
                // Otherwise no change
                (e1, e2) => Exp::Plus(Box::new(e1), Box::new(e2)),
            }
        }

        // Leave constants and variables unchanged
        other => other,
    }
}

